		scwin.getType = function(info) {
		   var rowIndex         = info.rowIndex;
         var colIndex        = info.colIndex;
         var colId           = info.colID;
         var returnInfo      = "";
         var itm_typ_cd1     = "";
         var itm_typ_cd2     = "";
         var brws_col_1_id   = "";
         var brws_col_2_id   = "";
         var textMaxLen      = 0;
         var readOnlyFlag    = false;
         var getterAplyFlag  = false;
         var inputType    = ""; 

         dst_tr04_out_01.setEventPause(null, true);

         if ( colId == "brws_col_1_val" ) {  

             itm_typ_cd1     = dst_tr04_out_01.getCellData( rowIndex , "itm_typ_cd1"     );  
             brws_col_1_id   = dst_tr04_out_01.getCellData( rowIndex , "brws_col_1_id"   );

             if ( ngmf.length(brws_col_1_id) > 0 ) { 
                 inputType = itm_typ_cd1;
             } else {
                 inputType = "text_disable";
             }

             dst_tr04_out_01.setCellData( rowIndex , "itm_typ_cd1", inputType    ); 

         } else if ( colId == "brws_col_2_val" ) {

             itm_typ_cd2     = dst_tr04_out_01.getCellData( rowIndex , "itm_typ_cd2"     );  
             brws_col_2_id   = dst_tr04_out_01.getCellData( rowIndex , "brws_col_2_id"   );

             if ( ngmf.length(brws_col_2_id) > 0 ) { 
                 inputType = itm_typ_cd2;
             } else {
                 inputType = "text_disable";
             }

             dst_tr04_out_01.setCellData( rowIndex , "itm_typ_cd2", inputType    );

         }  

         switch(inputType) 
         {

             // 예/아니오
             case "sel_yn":  // id : "dynamic_select_" + rowIndex + "_" + colIndex,  ==> 이렇게 하면 이상해짐????
                  returnInfo = {
                      id : "dynamic_"+inputType +  "_" + rowIndex + "_" + colIndex,
                      inputType : "select",
                      options : {
                          viewType: "icon"
                      },
                      itemSet : {
                          nodeset: "data:dsl_yn", 
                          label: "comm_cd_val_nm",
                          value: "comm_cd_val"
                      }
                  }
                  break; 

             //calendar 
             case "cal":     
                  returnInfo = {
                      id : "dynamic_"+inputType +  "_" + rowIndex + "_" + colIndex,
                      inputType : "calendar",
                      options : {
                          viewType: "icon",
                          dateValidCheck:"false",
                          displayFormat:"####-##-##"
                      }
                  }
                  break;

             //textImage
             case "img": 
                  returnInfo = {
                      id : "dynamic_"+inputType +  "_" + rowIndex + "_" + colIndex,
                      inputType : "textImage",
                      options : {
                                  viewType: "icon",
                                  imageSrc : "../../lib/images/btn_lov.png",
                                  imageWidth : "20",
                                  textAlign : "left"
                              }

                  }
                  break;

             case "lov": 
                 returnInfo = {
                      id : "dynamic_"+inputType +  "_" + rowIndex + "_" + colIndex,
                     inputType : "textImage",
                     options : {
                                 viewType: "icon",
                                 imageSrc : "../../lib/images/btn_lov.png",
                                 imageClickFunction : "scwin.grd_onExpandEdit",
                                 imageWidth : "20",
                                 textAlign : "left"
                             }

                    }
                    break;


             //text 
             case "text":    
                  returnInfo = {
                      id : "dynamic_"+inputType +  "_" + rowIndex + "_" + colIndex,
                      inputType : "text",
                      options : {
